// Function node to merge configuration
// This handles both first run (from Configuration) and loop runs (from Wait)

const originalConfig = $node.Configuration.json;
const currentInput = $json;

console.log('Current input:', JSON.stringify(currentInput, null, 2));
console.log('Original config:', JSON.stringify(originalConfig, null, 2));

// Determine if this is first run or loop run
const isFirstRun = !currentInput.should_continue && !currentInput.processed_page;

let config;
if (isFirstRun) {
  config = originalConfig;
  console.log('First run detected - using original config');
} else {
  config = {
    programming_language: currentInput.programming_language || originalConfig.programming_language,
    sort_by: currentInput.sort_by || originalConfig.sort_by,
    spreadsheet_id: currentInput.spreadsheet_id || originalConfig.spreadsheet_id,
    sheet_name: currentInput.sheet_name || originalConfig.sheet_name,
    results_per_page: currentInput.results_per_page || originalConfig.results_per_page,
    max_pages: currentInput.max_pages || originalConfig.max_pages,
    current_page: currentInput.current_page || originalConfig.current_page,
    include_code_metrics: currentInput.include_code_metrics !== undefined ? currentInput.include_code_metrics : originalConfig.include_code_metrics,
    max_file_size_kb: currentInput.max_file_size_kb || originalConfig.max_file_size_kb
  };
  console.log('Loop run detected - using updated config');
}

console.log(`Final config - Page: ${config.current_page}`);

return [{ json: config }];

// Summary of processing
const processedPage = $json.processed_page;
const totalResults = $json.total_results;
const totalPages = $json.total_pages;

return [{
  json: {
    status: 'completed',
    message: `Successfully processed ${processedPage} page(s) of GitHub repositories`,
    total_results_found: totalResults,
    total_pages_available: totalPages,
    pages_processed: processedPage,
    timestamp: new Date().toISOString()
  }
}];

// Corrected Check Pagination Logic
const searchResults = $node['Search GitHub Repos'].json;
const originalConfig = $node.Configuration.json;

// The current page that was just processed
const currentPageJustProcessed = $node.Code.json.current_page;

console.log('Page that was just processed:', currentPageJustProcessed);
console.log('Search results total:', searchResults.total_count);

const totalResults = searchResults.total_count;
const resultsPerPage = originalConfig.results_per_page;
const maxPages = originalConfig.max_pages;

const totalPages = Math.ceil(totalResults / resultsPerPage);
const nextPage = currentPageJustProcessed + 1;
const shouldContinue = nextPage <= totalPages && nextPage <= maxPages;

console.log(`Just processed page: ${currentPageJustProcessed}`);
console.log(`Next page would be: ${nextPage}`);
console.log(`Total pages: ${totalPages}`);
console.log(`Should continue: ${shouldContinue}`);

return [{
  json: {
    should_continue: shouldContinue,
    total_results: totalResults,
    total_pages: totalPages,
    processed_page: currentPageJustProcessed,
    // Pass the complete config with updated page for NEXT iteration
    programming_language: originalConfig.programming_language,
    sort_by: originalConfig.sort_by,
    spreadsheet_id: originalConfig.spreadsheet_id,
    sheet_name: originalConfig.sheet_name,
    results_per_page: originalConfig.results_per_page,
    max_pages: originalConfig.max_pages,
    current_page: nextPage,
    include_code_metrics: originalConfig.include_code_metrics,
    max_file_size_kb: originalConfig.max_file_size_kb
  }
}];

const items = [];

for (const item of $input.all()) {
  const data = item.json;
  const repo = data.repo || data;
  const metrics = data.code_metrics || {};

  // Debug logging to see what data we have
  console.log('Processing repo:', repo.full_name);
  console.log('actual_issues_count:', repo.actual_issues_count);
  console.log('actual_prs_count:', repo.actual_prs_count);
  console.log('original open_issues_count:', repo.open_issues_count);

  items.push({
    json: {
      repo_name: repo.name,
      full_name: repo.full_name,
      owner: repo.owner.login,
      description: repo.description || '',
      url: repo.html_url,
      stars: repo.stargazers_count,
      forks: repo.forks_count,
      // Use the corrected counts from Code1 node
      open_issues: metrics.actual_issues_count || 0,
      open_pull_requests:  metrics.actual_prs_count || 0,
      // Also include the original combined count for reference
      original_combined_open_count: repo.open_issues_count,
      watchers: repo.subscribers_count !== undefined ? repo.subscribers_count : repo.watchers_count,
      language: repo.language || '',
      created_at: repo.created_at,
      updated_at: repo.updated_at,
      pushed_at: repo.pushed_at,
      size: repo.size,
      default_branch: repo.default_branch,
      topics: repo.topics ? repo.topics.join(', ') : '',
      license: repo.license ? repo.license.name : '',
      is_private: repo.private,
      is_archived: repo.archived,
      has_issues: repo.has_issues,
      has_wiki: repo.has_wiki,
      has_pages: repo.has_pages,
      // Fixed code metrics with proper field mapping
      total_lines_of_code: metrics.total_lines || 0,
      total_non_empty_lines: metrics.total_non_empty_lines || 0,
      total_characters: metrics.total_characters || 0,
      total_code_files: metrics.total_code_files_found || 0,
      analyzed_files: metrics.files_successfully_analyzed || 0,
      failed_files: metrics.files_failed_to_analyze || 0,
      attempted_files: metrics.files_attempted_to_analyze || 0,
      avg_lines_per_file: metrics.avg_lines_per_file || 0,
      avg_chars_per_file: metrics.avg_chars_per_file || 0,
      avg_non_empty_lines_per_file: metrics.avg_non_empty_lines_per_file || 0,
      analysis_coverage_percent: metrics.analysis_coverage_percent || 0,
      primary_language: metrics.primary_language || repo.language || '',
      processed_at: new Date().toISOString()
    }
  });
}

return items;

// Merge repository data with code metrics
const items = $input.all();
const repo = items[0].json.repo || items[0].json;
const metrics = items[0].json.code_metrics || {};

return [{
  json: {
    repo,
    code_metrics: metrics
  }
}];

const allFiles = $input.all();
const repoData = $node['Filter Code Files'].json;
const enhancedRepo2 = $node['Code1'].json;

// Get the enhanced repo data from Code1 via the chain
// The repo data should have actual_issues_count and actual_prs_count
const enhancedRepo = repoData.repo;

let totalLines = 0;
let totalNonEmptyLines = 0;
let totalCharacters = 0;
let validProcessedFiles = 0;
let totalAttemptedFiles = 0;

console.log(`Aggregating metrics from ${allFiles.length} file processing results`);
console.log('Enhanced repo data includes actual_issues_count:', enhancedRepo.actual_issues_count);
console.log('Enhanced repo data includes actual_prs_count:', enhancedRepo.actual_prs_count);

// Sum up all metrics from all files processed in this execution
for (const item of allFiles) {
  totalAttemptedFiles++;

  if (item.json && typeof item.json.lines === 'number') {
    // Only count files that were successfully processed
    if (item.json.processing_success && item.json.is_valid_code_file) {
      totalLines += item.json.lines;
      totalNonEmptyLines += item.json.non_empty_lines || 0;
      totalCharacters += item.json.characters || 0;
      validProcessedFiles++;

      console.log(`Valid file: ${item.json.file_path} - Lines: ${item.json.lines}, Chars: ${item.json.characters}`);
    } else {
      console.log(`Skipped invalid file: ${item.json.file_path || 'unknown'}`);
    }
  }
}

// Create comprehensive summary using the enhanced repo data
const summary = {
  repo: enhancedRepo, // This should now include actual_issues_count and actual_prs_count
  code_metrics: {
    actual_issues_count:enhancedRepo2.actual_issues_count,
    actual_prs_count:enhancedRepo2.actual_prs_count,
    total_lines: totalLines,
    total_non_empty_lines: totalNonEmptyLines,
    total_characters: totalCharacters,
    total_code_files_found: repoData.total_code_files || 0,
    files_attempted_to_analyze: totalAttemptedFiles,
    files_successfully_analyzed: validProcessedFiles,
    files_failed_to_analyze: totalAttemptedFiles - validProcessedFiles,
    primary_language: repoData.primary_language || '',
    avg_lines_per_file: validProcessedFiles > 0 ? Math.round(totalLines / validProcessedFiles) : 0,
    avg_chars_per_file: validProcessedFiles > 0 ? Math.round(totalCharacters / validProcessedFiles) : 0,
    avg_non_empty_lines_per_file: validProcessedFiles > 0 ? Math.round(totalNonEmptyLines / validProcessedFiles) : 0,
    analysis_coverage_percent: repoData.total_code_files > 0 ? 
      Math.round((validProcessedFiles / repoData.total_code_files) * 100) : 0
  }
};

console.log(`=== AGGREGATION SUMMARY ===`);
console.log(`Total code files found: ${summary.code_metrics.total_code_files_found}`);
console.log(`Files attempted to analyze: ${summary.code_metrics.files_attempted_to_analyze}`);
console.log(`Files successfully analyzed: ${summary.code_metrics.files_successfully_analyzed}`);
console.log(`Total lines of code: ${summary.code_metrics.total_lines}`);
console.log(`Total non-empty lines: ${summary.code_metrics.total_non_empty_lines}`);
console.log(`Total characters: ${summary.code_metrics.total_characters}`);
console.log(`Analysis coverage: ${summary.code_metrics.analysis_coverage_percent}%`);
console.log(`Actual issues count: ${summary.repo.actual_issues_count}`);
console.log(`Actual PRs count: ${summary.repo.actual_prs_count}`);

return [{ json: summary }];

const fileData = $input.all();
const results = [];

console.log(`Processing ${fileData.length} files in this batch`);

for (let i = 0; i < fileData.length; i++) {
  const item = fileData[i];
  let content = '';
  let lines = 0;
  let characters = 0;
  let nonEmptyLines = 0;
  let isValidFile = false;

  try {
    // Extract content from various possible response formats
    if (item.binary && item.binary.data && item.binary.data.data) {
      // Handle binary response (base64 encoded)
      content = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
      isValidFile = true;
    } else if (typeof item.json === 'string') {
      // Direct string content
      content = item.json;
      isValidFile = true;
    } else if (item.json && typeof item.json.data === 'string') {
      // Content in data property
      content = item.json.data;
      isValidFile = true;
    } else if (item.json && typeof item.json.content === 'string') {
      // Content in content property
      content = item.json.content;
      isValidFile = true;
    } else if (item.data && typeof item.data === 'string') {
      // Content directly in data
      content = item.data;
      isValidFile = true;
    }

    if (content && typeof content === 'string' && isValidFile) {
      // Count total characters
      characters = content.length;

      // Split into lines (handle different line endings: \n, \r\n, \r)
      const lineArray = content.split(/\r\n|\r|\n/);
      lines = lineArray.length;

      // Handle edge case: if file doesn't end with newline, but has content
      if (content.length > 0 && !content.match(/[\r\n]$/)) {
        // File has content but no trailing newline - lines count is correct
      } else if (content.length > 0 && content.match(/[\r\n]$/)) {
        // File ends with newline - last "line" is empty, so subtract 1
        lines = Math.max(1, lines - 1);
      }

      // Count non-empty lines (excluding whitespace-only lines)
      nonEmptyLines = lineArray.filter(line => line.trim().length > 0).length;

      console.log(`File ${i} (${item.json?.path || 'unknown'}): ${lines} lines, ${nonEmptyLines} non-empty, ${characters} chars`);
    } else {
      console.log(`File ${i}: No valid content found or failed to fetch`);
      isValidFile = false;
    }
  } catch (error) {
    console.error(`Error processing file ${i}:`, error.message);
    isValidFile = false;
  }

  // Create result with metrics
  results.push({
    json: {
      lines: lines,
      non_empty_lines: nonEmptyLines,
      characters: characters,
      file_index: i,
      file_path: item.json?.path || `file_${i}`,
      file_size: item.json?.size || 0,
      content_length: content.length,
      processing_success: isValidFile && (lines > 0 || characters > 0),
      is_valid_code_file: isValidFile
    }
  });
}

console.log(`Batch complete: ${results.length} files processed`);
return results;

const repo = $node['Get Repo Details'].json;
const tree = $json;
const maxFileSizeKB = $node.Configuration.json.max_file_size_kb || 500;
const maxFileSize = maxFileSizeKB * 1024;

// Paths to skip (based on your reference)
const pathsToSkip = [
  'node_modules', '.git', 'dist', 'build', 'vendor',
  '.github', 'examples', 'docs', 'test', 'tests'
];

// Common code file extensions
const codeExtensions = {
  javascript: ['.js', '.jsx', '.ts', '.tsx', '.mjs', '.cjs'],
  python: ['.py', '.pyw', '.pyx', '.pxd', '.pxi'],
  java: ['.java'],
  c: ['.c', '.h'],
  cpp: ['.cpp', '.cc', '.cxx', '.hpp', '.h', '.hxx'],
  csharp: ['.cs'],
  go: ['.go'],
  rust: ['.rs'],
  php: ['.php', '.phtml', '.php3', '.php4', '.php5', '.php7', '.phps'],
  ruby: ['.rb', '.rake', '.gemspec'],
  swift: ['.swift'],
  kotlin: ['.kt', '.kts'],
  scala: ['.scala', '.sc'],
  // Generic extensions
  generic: ['.json', '.xml', '.yaml', '.yml', '.md', '.txt', '.sh', '.bat', '.sql']
};

// Helper function to check if file should be skipped
function shouldSkipFile(path) {
  return pathsToSkip.some(skip => path.includes(skip));
}

// Helper function to check if file is a code file
function isCodeFile(fileName) {
  const primaryLang = (repo.language || '').toLowerCase();
  const langExtensions = codeExtensions[primaryLang] || [];
  const allExtensions = [...new Set([...langExtensions, ...codeExtensions.generic])];

  const lowerFileName = fileName.toLowerCase();
  return allExtensions.some(ext => lowerFileName.endsWith(ext));
}

// Filter and prepare code files with content URLs
const codeFiles = tree.tree.filter(item => {
  if (item.type !== 'blob') return false;
  if (item.size > maxFileSize) return false;
  if (shouldSkipFile(item.path)) return false;
  return isCodeFile(item.path);
});

// Add content URLs to each file
const filesWithUrls = codeFiles.map(file => ({
  ...file,
  content_url: `https://raw.githubusercontent.com/${repo.full_name}/${repo.default_branch}/${file.path}`,
  raw_api_url: `https://api.github.com/repos/${repo.full_name}/contents/${file.path}`
}));

// Limit files to process
const maxFilesToProcess = 100; // Adjust as needed
const filesToProcess = filesWithUrls.slice(0, maxFilesToProcess);

console.log(`Total code files found: ${codeFiles.length}`);
console.log(`Files to process: ${filesToProcess.length}`);
console.log(`Skipping paths containing: ${pathsToSkip.join(', ')}`);

return [{
  json: {
    repo,
    files_to_process: filesToProcess,
    total_code_files: codeFiles.length,
    processed_files_count: filesToProcess.length,
    primary_language: repo.language || '',
    skipped_patterns: pathsToSkip
  }
}];

// Code node to parse exact counts from GitHub Search API
const repo = $node['Get Repo Details'].json;
const issuesSearchResponse = $node['Get Exact Issues Count'].json;
const prsSearchResponse = $node['Get Exact PRs Count'].json;

// Extract exact counts from search API responses
const actualIssuesCount = repo.has_issues ? (issuesSearchResponse.total_count || 0) : 0;
const actualPRsCount = prsSearchResponse.total_count || 0;

console.log(`Repository: ${repo.full_name}`);
console.log(`Has issues enabled: ${repo.has_issues}`);
console.log(`Original combined open_issues_count: ${repo.open_issues_count}`);
console.log(`Exact issues count: ${actualIssuesCount}`);
console.log(`Exact PRs count: ${actualPRsCount}`);
console.log(`Total (should match original): ${actualIssuesCount + actualPRsCount}`);

return [{
  json: {
    ...repo,
    actual_issues_count: actualIssuesCount,
    actual_prs_count: actualPRsCount,
    original_combined_count: repo.open_issues_count
  }
}];
